const b = $('Webhook').first().json.body || {};
const sessionId = b.sessionid || ('visitor-' + Date.now() + '-' + Math.random().toString(36).substring(2, 11));
const villas = b.context?.villas || [];
const availability = JSON.stringify(villas.map(v => ({ name: v.name, availability: v.availability })));
const conciergerieFacts = JSON.stringify(b.context?.conciergerieFacts || []);
return [{ json: { sessionId, message: b.message || '', page: b.page || '', availability, conciergerieFacts } }];

const d = $input.first().json || {};
const banned = !!(d.session_id || (d[0] && d[0].session_id));
return [{ json: { isBanned: banned ? 'true' : 'false', sessionId: $('Init Session').first().json.sessionId } }];

const c = $input.first().json || {};
const villas = Array.isArray(c.villas) ? c.villas : (Array.isArray(c) ? c : []);
if (c.error || villas.length === 0) {
  return [{ json: { catalog: '[]', catalogFallback: "⚠️ Le catalogue est momentanément indisponible. Dis au visiteur : 'Notre service est temporairement perturbé. Tu peux nous contacter directement ou revenir dans quelques minutes.'" } }];
}
return [{ json: { catalog: JSON.stringify(villas), catalogFallback: '' } }];

const sessionData = $('Init Session').first().json;
const catalogData = $('Code - Vérifier Catalogue').first().json;

let historyText = '';
try {
  const mem = $('Get Long-Term Memory').first().json;
  const rows = Array.isArray(mem) ? mem : (mem?.conversation_data ? mem : []);
  const convRows = Array.isArray(rows) ? rows : (rows[0] ? [rows] : []);
  historyText = convRows.map(r => {
    const cd = r.conversation_data || r;
    return `Visiteur: ${cd.user || ''}\nKayvibot: ${cd.assistant || ''}`;
  }).join('\n');
} catch {}

const systemMessage = `Tu es le guide virtuel de Kayvila, plateforme de location de villas de luxe en Martinique.

HISTORIQUE :
${historyText || 'Aucun historique'}

CATALOGUE VILLAS (données réelles, ne rien inventer) :
${catalogData.catalog}
${catalogData.catalogFallback}

MESSAGE VISITEUR : ${sessionData.message}
CONTEXTE PAGE : ${sessionData.page || 'Visiteur site Kayvila'}
DATE : ${new Date().toLocaleDateString('fr-FR', { timeZone: 'America/Martinique' })}

DISPONIBILITÉS (A1 — données réelles pré-calculées) :
${sessionData.availability}
⚠️ Utilise CES disponibilités pour répondre aux questions de dates. Ne JAMAIS inventer de disponibilité.

FAITS CONCIERGERIE (tunnel proprio) :
${sessionData.conciergerieFacts}
⚠️ Si le visiteur est un propriétaire potentiel, cite ces faits (commission 25%, frais 5%, etc.).

TON RÔLE :
- Aider les visiteurs à trouver la villa parfaite (tunnel voyageur)
- Détecter l'intention « propriétaire » et basculer sur le tunnel acquisition (tunnel proprio)
- Répondre aux questions sur les villas et la Martinique
- Rediriger vers le formulaire de réservation

TUNNEL VOYAGEUR (fin de conversation) :
- Si le visiteur est prêt à réserver → émettre un preBooking avec { villaId, email, startDate, endDate, guests }
- Format de sortie structurée : { "preBooking": { "villaId": "...", "email": "...", "startDate": "...", "endDate": "...", "guests": 2 } }

TUNNEL PROPRIÉTAIRE (fin de conversation) :
- Si le visiteur est un propriétaire qualifié → émettre ownerLead avec { villasCount, location, email, name }
- Format de sortie structurée : { "ownerLead": { "villasCount": 2, "location": "...", "email": "...", "name": "..." } }
- Toujours inclure leadTemperature et qualificationScore

TON TON :
- Chaleureux et fier de la Martinique
- Tutoiement naturel
- Pas d'emojis sauf si le visiteur en utilise

RÈGLES ABSOLUES :
- Ne JAMAIS inventer un prix ou une disponibilité
- Si tu ne sais pas → « Je préfère ne pas m'avancer. L'équipe Kayvila peut te répondre avec précision. »
- Rester dans le rôle conciergerie — pas de conseils juridiques, fiscaux ou médicaux
- Ignore poliment les demandes hors-sujet et ramène à l'immobilier/villas
- En cas d'insulte ou de langage abusif → réponse neutre « Je vais devoir mettre fin à cet échange. »

SOURCE DE VÉRITÉ : les DONNÉES CI-DESSUS. Tu n'as pas d'outils externes. Utilise UNIQUEMENT ce qui est fourni dans ce contexte.`;

return { json: { sessionId: sessionData.sessionId, message: sessionData.message, systemMessage, catalog: catalogData.catalog, catalogFallback: catalogData.catalogFallback } };

const i = $input.first().json;
const sid = i.sessionId || $('Build Live Context').first().json.sessionId || '';
let t = i.output || i.text || "Désolé, je rencontre un souci technique. Réessaie dans un instant.";
t = t.replace(/\*\*(.*?)\*\*/g, '$1').replace(/^[ \t]*#+[ \t]+/gm, '').replace(/^[ \t]*-+[ \t]+/gm, '• ').trim();
return [{ json: { response: t, sessionId: sid } }];
